1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	
45	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
46	  alikeItems.length === BLOCK_SIZE;
47	
48	const CURSE_SURCHARGE_RATE = 0.5;
49	
50	const curseSurchargeOn = (item: Item): number =>
51	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
52	
53	const sumOfBasePremiums = (items: Item[]): number =>
54	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
55	
56	const HIGH_ENCHANTMENT_LEVEL = 5;
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	
59	const highEnchantmentSurchargeOn = (item: Item): number =>
60	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
61	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
62	    : 0;
63	
64	const itemSurchargesOn = (items: Item[]): number =>
65	  items.reduce(
66	    (sum, item) => sum + curseSurchargeOn(item) + highEnchantmentSurchargeOn(item),
67	    0,
68	  );
69	
70	const typesOf = (items: Item[]): string[] => [...new Set(items.map((item) => item.type))];
71	
72	const groupedByType = (items: Item[]): Item[][] =>
73	  typesOf(items).map((type) => items.filter((item) => item.type === type));
74	
75	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
76	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
77	
78	const policyBaseOf = (items: Item[]): number =>
79	  groupedByType(items).reduce((sum, group) => sum + basePremiumOfAlikeItems(group), 0);
80	
81	// Rounding always favours the MHPCO: premiums up, payouts down.
82	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
83	
84	const firstInsuranceSurchargeOn = (policyBase: number): number =>
85	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
86	
87	// Policy-wide modifiers are percentages of the UNMODIFIED policy base — never of
88	// a base that already includes the item surcharges.
89	const policyModifiersOn = (policyBase: number): number =>
90	  firstInsuranceSurchargeOn(policyBase);
91	
92	const quoteFor = (items: Item[]): Result => {
93	  const policyBase = policyBaseOf(items);
94	  return {
95	    premium: premiumRoundedInMHPCOsFavour(
96	      policyBase + itemSurchargesOn(items) + policyModifiersOn(policyBase) + PROCESSING_FEE,
97	    ),
98	  };
99	};
100	
101	const resultFor = (step: Step): Result => {
102	  if (step.op === "quote") return quoteFor(step.items);
103	  throw new Error(`unsupported step: ${step.op}`);
104	};
105	
106	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
107	  results: scenario.steps.map(resultFor),
108	});
