const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

// Every item-specific surcharge is a rate on THAT item's base premium, charged
// when its risk applies. Adding a new one means adding a row here — nothing else.
type ItemSurcharge = { appliesTo: (item: Item) => boolean; rate: number };

const ITEM_SURCHARGES: ItemSurcharge[] = [
  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
];

const surchargeRateOn = (item: Item): number =>
  ITEM_SURCHARGES.reduce(
    (rate, surcharge) => (surcharge.appliesTo(item) ? rate + surcharge.rate : rate),
    0,
  );

const itemSurchargesOn = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
